#[kani::proof]
fn certificate(){use solana_program::{account_info::AccountInfo,pubkey::Pubkey,program_error::ProgramError};
let k0=Pubkey::new_from_array(kani::any()); let mut l0:u64=kani::any(); let mut d0=[kani::any::<u8>()]; let a0=AccountInfo::new(&k0,false,true,&mut l0,&mut d0,&k0,false,0);
let k1=Pubkey::new_from_array(kani::any()); let mut l1:u64=kani::any(); let mut d1=[kani::any::<u8>()]; let a1=AccountInfo::new(&k1,false,true,&mut l1,&mut d1,&k1,false,0);
kani::assume(k0!=k1); let before0=a0.lamports(); let before1=a1.lamports(); let data_before=a0.try_borrow_data().unwrap()[0];
let ambient=a0.try_borrow_data().unwrap();
let result=super::close_program_account_v1(&a0,&a1,&k0,1);
assert!(result==Err(ProgramError::AccountBorrowFailed)); assert!(a0.lamports()==before0); assert!(a1.lamports()==before1);
assert!(a0.try_borrow_data().unwrap()[0]==data_before);
drop(ambient);
assert!(a0.try_borrow_mut_data().is_ok());assert!(a1.try_borrow_mut_data().is_ok());assert!(a0.try_borrow_mut_lamports().is_ok());assert!(a1.try_borrow_mut_lamports().is_ok());
}
